package com.geekmall.aftersale;import com.geekmall.common.api.BusinessException;import java.util.*;
final class AftersaleStateMachine {private static final Map<String,Set<String>> NEXT=Map.of("APPLIED",Set.of("APPROVED","REJECTED","CANCELLED"),"REJECTED",Set.of("ARBITRATING"),"APPROVED",Set.of("RETURNING","REFUNDING","EXCHANGING","REPAIRING"),"RETURNING",Set.of("RECEIVED"),"RECEIVED",Set.of("REFUNDING","EXCHANGING"),"REFUNDING",Set.of("COMPLETED"),"EXCHANGING",Set.of("COMPLETED"),"REPAIRING",Set.of("COMPLETED"),"ARBITRATING",Set.of("APPROVED","REJECTED"));static void require(String from,String to){if(!NEXT.getOrDefault(from,Set.of()).contains(to))throw new BusinessException("AS40901","售后状态不可从 "+from+" 转换为 "+to);}}
